 "content": "def transform(grid):
    """Keep and repair coherent, near-solid colored rectangles; treat other cells as noise."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = set(v for row in grid for v in row if v != bg)
    candidates = []
    for color in colors:
        # Integral image for fast rectangle counts.
        sat = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            run = 0
            for c in range(w):
                run += grid[r][c] == color
                sat[r + 1][c + 1] = sat[r][c + 1] + run
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                rh = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = rh * (c1 - c0 + 1)
                        if area < 6:
                            continue
                        n = sat[r1 + 1][c1 + 1] - sat[r0][c1 + 1] - sat[r1 + 1][c0] + sat[r0][c0]
                        density = n / area
                        if density >= 0.72:
                            candidates.append((area, density, color, r0, r1, c0, c1))
    candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
    out = [[bg] * w for _ in range(h)]
    occupied = [[False] * w for _ in range(h)]
    for area, density, color, r0, r1, c0, c1 in candidates:
        # The largest valid rectangle claims its cells; nested subrectangles are redundant.
        if any(occupied[r][c] for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)):
            continue
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                occupied[r][c] = True
                out[r][c] = color
    return out
